import {
  BookingQueuePassResponseItem,
  GiftsResponseItem,
  ProductsResponseItem,
  VisitorResponseItem,
  OrderSummaryResponseItem,
  OrderDetailsResponse,
  SavedNetsPaymentMethodResponse,
  GiftItem,
} from "@parksandresorts/myparks-types";

export enum AuthActionTypes {
  DEBUG = "DEBUG",
  SESSION_CREATED = "SESSION_CREATED",
  SESSION_UPDATED = "SESSION_UPDATED",
  SESSION_DELETED = "SESSION_DELETED",
  SERVER_ERROR = "SERVER_ERROR",
  USER_PRODUCTS_UPDATED = "USER_PRODUCTS_UPDATED",
  CARD_REGISTERED = "CARD_REGISTERED",
  CARD_BOOKING_SUCCESSFUL = "CARD_BOOKING_SUCCESSFUL",
  FETCH_PRODUCTS_REQUEST = "FETCH_PRODUCTS_REQUEST",
  FETCH_PRODUCTS_SUCCESS = "FETCH_PRODUCTS_SUCCESS",
  FETCH_PRODUCTS_FAILURE = "FETCH_PRODUCTS_FAILURE",
  FETCH_GIFTS_REQUEST = "FETCH_GIFTS_REQUEST",
  FETCH_GIFTS_SUCCESS = "FETCH_GIFTS_SUCCESS",
  FETCH_GIFTS_FAILURE = "FETCH_GIFTS_FAILURE",
  FETCH_CONTACTLESS_SUMMARIES_REQUEST = "FETCH_CONTACTLESS_SUMMARIES_REQUEST",
  FETCH_CONTACTLESS_SUMMARIES_SUCCESS = "FETCH_CONTACTLESS_SUMMARIES_SUCCESS",
  FETCH_CONTACTLESS_SUMMARIES_FAILURE = "FETCH_CONTACTLESS_SUMMARIES_FAILURE",
  FETCH_CONTACTLESS_DETAILS_REQUEST = "FETCH_CONTACTLESS_DETAILS_REQUEST",
  FETCH_CONTACTLESS_DETAILS_SUCCESS = "FETCH_CONTACTLESS_DETAILS_SUCCESS",
  FETCH_CONTACTLESS_DETAILS_FAILURE = "FETCH_CONTACTLESS_DETAILS_FAILURE",
  FETCH_SESSION_FAILURE = "FETCH_SESSION_FAILURE",
  FETCH_SESSION_REQUEST = "FETCH_SESSION_REQUEST",
  CONTACTLESS_VISITORS_UPDATED = "CONTACTLESS_VISITORS_UPDATED",
  SET_CONTACTLESS_VISITORS = "SET_CONTACTLESS_VISITORS",
  SET_SAVED_PAYMENT_METHOD = "SET_SAVED_PAYMENT_METHOD",
}

export type UserProductUpdatedAction = {
  type: AuthActionTypes.USER_PRODUCTS_UPDATED;
  payload: {
    userProducts: ProductsResponseItem;
    productsFetchTime?: string;
  };
};

export type DebugAction = {
  type: AuthActionTypes.DEBUG;
  payload?: any;
};

export type SessionCreatedAction = {
  type: AuthActionTypes.SESSION_CREATED;
  payload?: any;
};

export type SessionUpdatedAction = {
  type: AuthActionTypes.SESSION_UPDATED;
  payload?: any;
};

export type SessionDeletedAction = {
  type: AuthActionTypes.SESSION_DELETED;
  payload?: any;
};

export type ServerErrorAction = {
  type: AuthActionTypes.SERVER_ERROR;
  payload?: any;
};

export type CardRegisteredAction = {
  type: AuthActionTypes.CARD_REGISTERED;
  payload?: any;
};

export type CardBookingSuccessfulAction = {
  type: AuthActionTypes.CARD_BOOKING_SUCCESSFUL;
  payload: { bookings: Array<BookingQueuePassResponseItem>; productId: any };
};

export type FetchProductsRequestAction = {
  type: AuthActionTypes.FETCH_PRODUCTS_REQUEST;
  payload?: undefined;
};

export type FetchProductsSuccessAction = {
  type: AuthActionTypes.FETCH_PRODUCTS_SUCCESS;
  payload: {
    userProducts: ProductsResponseItem;
    productsFetchTime?: string;
  };
};

export type FetchProductsFailureAction = {
  type: AuthActionTypes.FETCH_PRODUCTS_FAILURE;
  payload: {
    error: string;
  };
};

export type FetchGiftsRequestAction = {
  type: AuthActionTypes.FETCH_GIFTS_REQUEST;
};

export type FetchGiftsSuccessAction = {
  type: AuthActionTypes.FETCH_GIFTS_SUCCESS;
  payload: {
    giftsResponse: GiftsResponseItem;
  };
};

export type FetchGiftsFailureAction = {
  type: AuthActionTypes.FETCH_GIFTS_FAILURE;
};

export type FetchContactlessSummariesRequestAction = {
  type: AuthActionTypes.FETCH_CONTACTLESS_SUMMARIES_REQUEST;
};

export type FetchContactlessSummariesSuccessAction = {
  type: AuthActionTypes.FETCH_CONTACTLESS_SUMMARIES_SUCCESS;
  payload: {
    response: Array<OrderSummaryResponseItem>;
  };
};

export type FetchContactlessSummariesFailureAction = {
  type: AuthActionTypes.FETCH_CONTACTLESS_SUMMARIES_FAILURE;
};

export type FetchContactlessDetailsRequestAction = {
  type: AuthActionTypes.FETCH_CONTACTLESS_DETAILS_REQUEST;
  payload: {
    orderId: string;
  };
};

export type FetchContactlessDetailsSuccessAction = {
  type: AuthActionTypes.FETCH_CONTACTLESS_DETAILS_SUCCESS;
  payload: {
    orderId: string;
    response: OrderDetailsResponse;
  };
};

export type FetchContactlessDetailsFailureAction = {
  type: AuthActionTypes.FETCH_CONTACTLESS_DETAILS_FAILURE;
  payload: {
    orderId: string;
  };
};

export type FetchSessionFailureAction = {
  type: AuthActionTypes.FETCH_SESSION_FAILURE;
  payload?: any;
};

export type FetchSessionRequestAction = {
  type: AuthActionTypes.FETCH_SESSION_REQUEST;
  payload?: undefined;
};

export type ContactlessVisitorsUpdatedAction = {
  type: AuthActionTypes.CONTACTLESS_VISITORS_UPDATED;
  payload: {
    visitor: VisitorResponseItem;
  };
};

export type ContactlessVisitorsSetAction = {
  type: AuthActionTypes.SET_CONTACTLESS_VISITORS;
  payload: Record<number, VisitorResponseItem>;
};

export type SavedPaymentMethodAction = {
  type: AuthActionTypes.SET_SAVED_PAYMENT_METHOD;
  payload: SavedNetsPaymentMethodResponse;
};

export type AuthAction =
  | UserProductUpdatedAction
  | DebugAction
  | SessionCreatedAction
  | SessionUpdatedAction
  | SessionDeletedAction
  | ServerErrorAction
  | CardRegisteredAction
  | CardBookingSuccessfulAction
  | FetchProductsRequestAction
  | FetchProductsSuccessAction
  | FetchProductsFailureAction
  | FetchGiftsRequestAction
  | FetchGiftsSuccessAction
  | FetchGiftsFailureAction
  | FetchContactlessSummariesRequestAction
  | FetchContactlessSummariesSuccessAction
  | FetchContactlessSummariesFailureAction
  | FetchContactlessDetailsRequestAction
  | FetchContactlessDetailsSuccessAction
  | FetchContactlessDetailsFailureAction
  | FetchSessionFailureAction
  | FetchSessionRequestAction
  | ContactlessVisitorsUpdatedAction
  | ContactlessVisitorsSetAction
  | SavedPaymentMethodAction;

export type UserProperty = {
  /**
   * Represents the type of accessibility/companion property assigned to the user.
   * Acts as an enum with the following values:
   * - `0` — Ride assistance
   * - `1` — Ride assistance - movement impaired
   * - `2` — One companion
   * - `3` — Two companions
   * - `4` — No right to assistance
   * - `5` — No right to companion
   */
  PropertyType: number;
  ExpiresOn?: string | null;
  Comment?: string | null;
};

export type IUser = {
  altId: string;
  avatar?: string;
  birthDate: string;
  email: string;
  firstName: string;
  lastName: string;
  phoneNo: string;
  properties?: Array<UserProperty>;
};
export type IAuthState = {
  debugToggle: boolean;
  user?: IUser;
  antiCsrfToken?: string;
  loginMethod?: string;
  isLoggedIn: boolean;
  cookieString?: string;
  error?: boolean;
  errorSource?: any;
  productsFetchTime?: string;
  productsFetched?: boolean;
  isFetchingProducts: boolean;
  productFetchFailed: boolean;
  giftsFetchTime?: string;
  giftsFetched?: boolean;
  isFetchingGifts: boolean;
  giftFetchFailed: boolean;
  gifts: Array<GiftItem>;
  sessionFetchFailed?: boolean;
  sessionFetched: boolean;
  isFetchingSession: boolean;
  products?: ProductsResponseItem;
  contactlessOrders?: Array<OrderSummaryResponseItem>;
  isFetchingContactlessOrders: boolean;
  contactlessOrdersFetchFailed: boolean;
  contactlessOrderDetails: Record<string, { order?: OrderDetailsResponse; isFetching: boolean; fetchFailed: boolean }>;
  savedPaymentMethod: SavedNetsPaymentMethodResponse | null;
};

export type IAuthDispatch = React.Dispatch<AuthAction>;
