// @ts-strict-ignore
import { ProductApiResponse } from "../types/purchase/product-types";
import { PostGiftsApiFormat } from "../types/purchase/gift-types";
import axios from "axios";
import type { MyParksApiResponse } from "../types/my-parks-api-types";
import { RefundSummaryApiResponse } from "../types/purchase/refund-types";
import { IUser } from "../types/auth-types";
import {
  BookingQueuePassesResponseItem,
  GiftsResponseItem,
  GiftItem,
  BookingQueuePassRequestItem,
  BlockTagReason,
  BlockTagsRequest,
  EmptyApiResultItem,
  TagResponse,
  VisitorResponseItem,
  OrderSummaryResponseItemIEnumerableApiResultItem,
  OrderDetailsResponseApiResultItem,
  RegisterTagRequest,
  UpdateVisitorRequest,
  SavedNetsPaymentMethodResponse,
  ReplaceSavedNetsPaymentResponse,
  GamificationVisitorsVisitsResponseApiResultItem,
  RegisterSeasonPassVoucherRequestItem,
  RegisterCardRequestItem,
  ValidateSeasonPassResponse,
  RegisterSeasonPassResponse,
} from "@parksandresorts/myparks-types";

const ENDPOINT_SESSION = "session";
const ENDPOINT_SESSION_PIN = "session/pin";
const ENDPOINT_SESSION_PIN_VALIDATE = "session/pin/validate";
const ENDPOINT_PRODUCTS = "products";
const ENDPOINT_ORDER_ROWS = "products/order-rows";
const ENDPOINT_ORDER_REBOOK_DATES = "weborders/datetime";
const ENDPOINT_ORDER_REBOOK_PASSES = "weborders/queuepass";
const ENDPOINT_USERS = "users";
const ENDPOINT_GIFTS = "gifts";
const ENDPOINT_CARD_BOOKING = `queuepasses`;
const ENDPOINT_CONTACT_VERIFICATION = `contact-verification`;
const ENDPOINT_GAMIFICATION = `gamification/visitors-visits`;
const ENDPOINT_PARKING_PERMITS = `parkingpermits`;
const ENDPOINT_CONTACTLESS = `contactless`;
const ENDPOINT_SEASON_PASS_VOUCHER = `seasonpass`;

type IFetchOptions = {
  body?: object;
  contentType?: string;
  session?: string;
};

type HttpMethod = "POST" | "GET" | "PATCH" | "PUT" | "DELETE";

type InitiateSessionResponse = MyParksApiResponse<{
  antiCsrfToken: string;
  hasLoggedIn: boolean;
  loginMethod: string;
}>;
type PostVerificationCodeResponse = MyParksApiResponse<{
  antiCsrfToken: string;
  hasLoggedIn: boolean;
  user: IUser;
}>;

class MyParksService {
  url = null;
  company = null;
  language = "sv";
  antiCsrfToken = null;

  updateAuth(auth) {
    if (!auth) {
      return;
    }

    if (auth.antiCsrfToken) {
      this.antiCsrfToken = auth.antiCsrfToken;
    }
  }

  init(language, apiUrl, apiCompany) {
    this.language = language;
    this.url = apiUrl;
    this.company = apiCompany;
  }

  /** Session management */
  initiateSession(identifier: string, isAutoLoginToken?: boolean) {
    const identify = isAutoLoginToken ? { autoLoginToken: identifier } : { identifier: identifier };
    return this._authorizedFetch<InitiateSessionResponse>(ENDPOINT_SESSION_PIN, "POST", { body: identify });
  }

  postVerificationCode(code: string) {
    const postBody = { pin: code };
    return this._authorizedFetch<PostVerificationCodeResponse>(ENDPOINT_SESSION_PIN_VALIDATE, "POST", {
      body: postBody,
    });
  }

  fetchSession() {
    return this._authorizedFetch(ENDPOINT_SESSION, "GET");
  }

  deleteSession() {
    return this._authorizedFetch(ENDPOINT_SESSION, "DELETE");
  }

  getSessionCookie() {
    return document.cookie.replace(/(?:(?:^|.*;\s*)session\s*=\s*([^;]*).*$)|^.*$/, "$1");
  }

  /** Contactless */
  getContactlessVisitors() {
    return this._authorizedFetchWithPlainResponse<{ response: Array<VisitorResponseItem> }>(
      `${ENDPOINT_CONTACTLESS}/visitors`,
      "GET",
    );
  }

  getValidateContactlessVisitorTag(requestId: string) {
    return this._authorizedFetchWithPlainResponse<{ response: TagResponse } & EmptyApiResultItem>(
      `${ENDPOINT_CONTACTLESS}/tag/${requestId}`,
      "GET",
    );
  }

  postRegisterContactlessVisitorTag(visitorId: number, requestBody: RegisterTagRequest) {
    return this._authorizedFetchWithPlainResponse<{ response: VisitorResponseItem } & EmptyApiResultItem>(
      `${ENDPOINT_CONTACTLESS}/visitor/${visitorId}/registerTag`,
      "POST",
      {
        body: requestBody,
      },
    );
  }

  updateContactlessVisitor(visitorId: number, updatedFieldsBody: UpdateVisitorRequest) {
    return this._authorizedFetchWithPlainResponse<{ response: VisitorResponseItem }>(
      `${ENDPOINT_CONTACTLESS}/visitor/${visitorId}`,
      "PATCH",
      {
        body: updatedFieldsBody,
      },
    );
  }

  blockContactlessTag(shortIds: Array<string>, reason: BlockTagReason = BlockTagReason.GOING_HOME, comment?: string) {
    const requestBody: BlockTagsRequest = {
      reason: reason,
      shortIds: shortIds,
      comment: comment,
    };
    return this._authorizedFetchWithPlainResponse(`${ENDPOINT_CONTACTLESS}/tags`, "DELETE", {
      body: requestBody,
    });
  }

  getContactlessPaymentMethod() {
    return this._authorizedFetchWithPlainResponse<{ response: SavedNetsPaymentMethodResponse }>(
      `${ENDPOINT_CONTACTLESS}/savedPaymentMethod`,
      "GET",
    );
  }

  updateContactlessPaymentMethod(): Promise<ReplaceSavedNetsPaymentResponse> {
    return this._authorizedFetchWithPlainResponse<{ response: ReplaceSavedNetsPaymentResponse }>(
      `${ENDPOINT_CONTACTLESS}/savedPaymentMethod`,
      "PUT",
      {
        body: {
          paymentProvider: "Nets",
        },
      },
    );
  }

  deleteContactlessPaymentMethod(): Promise<EmptyApiResultItem> {
    return this._authorizedFetchWithPlainResponse<{ response: EmptyApiResultItem }>(
      `${ENDPOINT_CONTACTLESS}/savedPaymentMethod`,
      "DELETE",
    );
  }

  async getContactlessOrders() {
    return await this._authorizedFetchWithPlainResponse<Required<OrderSummaryResponseItemIEnumerableApiResultItem>>(
      `${ENDPOINT_CONTACTLESS}/orders`,
      "GET",
    );
  }

  getContactlessOrderDetails(orderId: string) {
    // TODO: test `?culture=${this.language}`
    return this._authorizedFetchWithPlainResponse<Required<OrderDetailsResponseApiResultItem>>(
      `${ENDPOINT_CONTACTLESS}/order/${orderId}`,
      "GET",
    );
  }

  getContactlessGamification() {
    return this._authorizedFetchWithPlainResponse<Required<GamificationVisitorsVisitsResponseApiResultItem>>(
      `${ENDPOINT_GAMIFICATION}`,
      "GET",
    );
  }

  /** User */

  updateUser(userAltId, updatedUser) {
    const endpoint = `${ENDPOINT_USERS}/${userAltId}`;
    return this._authorizedFetch(endpoint, "PATCH", { body: updatedUser });
  }

  /** Products */

  fetchProducts() {
    const endpoint = ENDPOINT_PRODUCTS;
    return this._authorizedFetch<ProductApiResponse>(endpoint, "GET");
  }

  /** Sharing */

  acceptSharing(giftId: string, giftToken: string) {
    return this.acceptGift(giftId, giftToken);
  }

  cancelSharing(giftId: number) {
    return this.cancelGift(giftId);
  }

  addSharing(data: PostGiftsApiFormat) {
    return this.sendGifts(data);
  }

  removeSharing(data /* : PostGiftsApiFormat */) {
    const endpoint = `${ENDPOINT_ORDER_ROWS}/stop-sharing`;
    return this._authorizedFetch(endpoint, "DELETE", { body: data });
  }

  getSharedProducts() {
    return this.getGifts();
  }

  getSharedProduct(productId: string, token: string) {
    return this.getGift(productId, token);
  }

  denySharedProduct(productId: string, token: string) {
    return this.denyGift(productId, token);
  }

  /** Gifts */

  getGift(giftId: string, token: string) {
    const endpoint = `${ENDPOINT_GIFTS}/${giftId}?token=${token}`;
    return this._fetchWithoutErrorHandling<MyParksApiResponse<GiftItem>>(endpoint, "GET");
  }

  sendGifts(data: PostGiftsApiFormat) {
    const endpoint = ENDPOINT_GIFTS;
    return this._authorizedFetch<MyParksApiResponse<GiftsResponseItem>>(endpoint, "POST", { body: data });
  }

  getGifts() {
    const endpoint = `${ENDPOINT_GIFTS}`;
    return this._authorizedFetch<MyParksApiResponse<GiftsResponseItem>>(endpoint, "GET");
  }

  acceptGift(giftId: string, giftToken: string) {
    const endpoint = `${ENDPOINT_GIFTS}/${giftId}?token=${giftToken}`;
    return this._authorizedFetch(endpoint, "PATCH");
  }

  cancelGift(giftId: number) {
    const endpoint = `${ENDPOINT_GIFTS}/${giftId}`;
    return this._authorizedFetch(endpoint, "DELETE");
  }

  denyGift(giftId: string, giftToken: string) {
    const endpoint = `${ENDPOINT_GIFTS}/${giftId}?token=${giftToken}`;
    return this._fetchWithoutErrorHandling(endpoint, "DELETE");
  }

  /** Card management */

  registerCard(orderRowId: string | number, user: Omit<RegisterCardRequestItem, "postalAddress" | "city">) {
    const endpoint = `${ENDPOINT_ORDER_ROWS}/${orderRowId}/season-pass-v2`;
    return this._authorizedFetch(endpoint, "POST", { body: user });
  }

  /** Parking */

  registerFreeParking(orderRowId, licenseNumber) {
    const endpoint = `${ENDPOINT_ORDER_ROWS}/${orderRowId}/free-parking`;
    return this._authorizedFetch(endpoint, "POST", { body: { vrm: licenseNumber } });
  }

  /** Order management */

  rebookOrderRows(bookingData) {
    const endpoint = `${ENDPOINT_ORDER_REBOOK_DATES}`;
    return this._authorizedFetch(endpoint, "PATCH", { body: bookingData });
  }

  rebookQueuePassesForOrderRows(bookingData) {
    const endpoint = `${ENDPOINT_ORDER_REBOOK_PASSES}`;
    return this._authorizedFetch(endpoint, "PATCH", { body: bookingData });
  }

  requestRefundSummary(orderType: number, orderNo: number, orderRows) {
    const endpoint = `${ENDPOINT_PRODUCTS}/orders/${orderType}/${orderNo}/refund-summary`;
    return this._authorizedFetch<RefundSummaryApiResponse>(endpoint, "POST", { body: orderRows });
  }

  refundOrderRows(orderType: number, orderNo: number, orderRows, finalRefundAmount: number) {
    const bodyObject = {
      finalRefundAmount: finalRefundAmount,
      rows: orderRows,
    };

    const endpoint = `${ENDPOINT_PRODUCTS}/orders/${orderType}/${orderNo}/refund`;
    return this._authorizedFetch(endpoint, "PATCH", { body: bodyObject });
  }

  /** JetPass Booking */

  //The myParksId is _probably_ not needed since we get it from the logged in session. Waiting for comfirmation before its deleted from the backend
  bookPassesForCards(cards: Array<Omit<BookingQueuePassRequestItem, "myParksId">>) {
    const endpoint = ENDPOINT_CARD_BOOKING;
    return this._authorizedFetch<MyParksApiResponse<BookingQueuePassesResponseItem>>(endpoint, "POST", { body: cards });
  }

  /** Register */

  postContactInformationForVerification(contactInformation) {
    const endpoint = ENDPOINT_CONTACT_VERIFICATION;
    return this._fetchWithoutErrorHandling(endpoint, "POST", { body: contactInformation });
  }

  getContactVerification(contactInformation, pinCode) {
    const endpoint = `${ENDPOINT_CONTACT_VERIFICATION}?contact=${contactInformation}&code=${pinCode}`;
    return this._fetchWithoutErrorHandling(endpoint, "GET");
  }

  registerUser(account, verificationCode) {
    const body = {
      account: account,
      contactVerificationToken: verificationCode,
    };

    const endpoint = ENDPOINT_USERS;
    return this._authorizedFetch<PostVerificationCodeResponse>(endpoint, "POST", { body: body });
  }

  /** Vouchers */
  async fetchVoucherDetails(cardNumber: string, pinCode: string) {
    const endpoint = `${ENDPOINT_SEASON_PASS_VOUCHER}/${cardNumber}/validate/${pinCode}`;

    return this._fetch<ValidateSeasonPassResponse>(endpoint, "GET");
  }

  async registerVoucher(registrationData: RegisterSeasonPassVoucherRequestItem) {
    const endpoint = `${ENDPOINT_SEASON_PASS_VOUCHER}/register-owner`;

    const response = await this._baseAuthorizedFetch<RegisterSeasonPassResponse>(endpoint, "PATCH", {
      body: registrationData,
    });
    return response.data;
  }

  /** Api utils */
  buildErrorResponse(error: any): never {
    if (error.response) {
      // The request was made and the server responded with a status code
      // that falls out of the range of 2xx
      throw {
        data: { ...error.response.data },
        status: error.response.status,
      };
    } else if (error.name === "AxiosError") {
      throw error;
    } else if (error.request) {
      // The request was made but no response was received
      // `error.request` is an instance of XMLHttpRequest in the browser and an instance of
      // http.ClientRequest in node.js
      throw {
        data: { statusCode: 503, success: false, errors: [] },
        status: 503,
      };
    } else {
      // Something happened in setting up the request that triggered an Error
      // console.error('Error', error.message);
      throw {
        data: { statusCode: 400, success: false, errors: [] },
        status: 400,
      };
    }
  }

  _baseAuthorizedFetch<Data>(endpoint: string, method: HttpMethod, options: IFetchOptions = {}) {
    if (!this.url || !this.company) {
      console.error(
        `MyParksService is missing configuration. Current configuration url: ${this.url} and company: ${this.company}`,
      );
      return undefined;
    }

    const body = options.body ? options.body : null;
    const contentType = options.contentType ? options.contentType : "application/json";

    const url = `${this.url}/${endpoint}`;
    return axios<Data>({
      method,
      url,
      headers: {
        "X-Company": this.company,
        "X-Language": this.language,
        "X-Cookie": this.getSessionCookie(),
        "X-AntiCsrfToken": this.antiCsrfToken,
        "content-type": contentType,
      },
      data: body,
      withCredentials: true,
    });
  }

  async _authorizedFetch<Data extends { response: object }>(
    endpoint: string,
    method: HttpMethod,
    options: IFetchOptions = {},
  ): Promise<Data["response"] & { cookieString: string }> {
    try {
      const response = await this._baseAuthorizedFetch<Data>(endpoint, method, options);
      return { ...response.data.response, cookieString: response.headers["x-cookie"] };
    } catch (error) {
      return this.buildErrorResponse(error);
    }
  }
  async _authorizedFetchWithPlainResponse<Data extends { response: object }>(
    endpoint: string,
    method: HttpMethod,
    options: IFetchOptions = {},
  ): Promise<Data["response"]> {
    try {
      const response = await this._baseAuthorizedFetch<Data>(endpoint, method, options);
      return response.data.response;
    } catch (error) {
      return this.buildErrorResponse(error);
    }
  }

  /**
   *
   * @deprecated Use _fetch instead. That method has built-in error handling and follows the new pattern of not assuming we have the MyParksApiResponse wrapper.
   */
  async _fetchWithoutErrorHandling<Data extends { response: object }>(
    endpoint: string,
    method: HttpMethod,
    options: IFetchOptions = {},
  ): Promise<Data["response"]> {
    if (!this.url || !this.company) {
      console.error(
        `MyParksService is missing configuration. Current configuration url: ${this.url} and company: ${this.company}`,
      );
      return undefined;
    }

    const body = options.body ? options.body : null;
    const contentType = options.contentType ? options.contentType : "application/json";

    const url = `${this.url}/${endpoint}`;
    const response = await axios<Data>({
      method: method,
      url,
      headers: {
        "X-Company": this.company,
        "X-Language": this.language,
        "content-type": contentType,
      },
      data: body,
    });

    return response.data.response;
  }

  async _fetch<Data>(endpoint: string, method: HttpMethod, options: IFetchOptions = {}): Promise<Data> {
    if (!this.url || !this.company) {
      console.error(
        `MyParksService is missing configuration. Current configuration url: ${this.url} and company: ${this.company}`,
      );
      return undefined;
    }

    const body = options.body ? options.body : null;
    const contentType = options.contentType ? options.contentType : "application/json";

    const url = `${this.url}/${endpoint}`;
    try {
      const response = await axios<Data>({
        method: method,
        url,
        headers: {
          "X-Company": this.company,
          "X-Language": this.language,
          "content-type": contentType,
        },
        data: body,
      });
      return response.data;
    } catch (error) {
      return this.buildErrorResponse(error);
    }
  }
}

const service = new MyParksService();

export default service;
