import { AuthActionTypes, AuthAction, IAuthState } from "../types/auth-types";

import { EntryTicketItem } from "@parksandresorts/myparks-types";
import { DateHelper, exhaustiveCheck, isNonEmptyArray, isTruthy } from "@/core/helpers/";

const initialAuthState: IAuthState = {
  debugToggle: false,
  user: undefined,
  antiCsrfToken: undefined,
  loginMethod: undefined,
  isLoggedIn: false,
  cookieString: undefined,
  productsFetched: false,
  isFetchingProducts: false,
  productFetchFailed: false,
  giftsFetched: false,
  isFetchingGifts: false,
  giftFetchFailed: false,
  gifts: [],
  sessionFetched: false,
  sessionFetchFailed: false,
  isFetchingSession: false,
  contactlessOrders: undefined,
  isFetchingContactlessOrders: false,
  contactlessOrdersFetchFailed: false,
  contactlessOrderDetails: {},
  savedPaymentMethod: null,
};

const entryTicketDateAscendingSort = (a: EntryTicketItem, b: EntryTicketItem): -1 | 0 | 1 => {
  const aNotBefore = a.validity?.notBefore;
  const bNotBefore = b.validity?.notBefore;

  // Put invalid data last in array
  if (!aNotBefore && !bNotBefore) return 0; // Both have invalid data
  if (!bNotBefore) return -1; // A has data, B has invalid data
  if (!aNotBefore) return 1; // A has invalid data, B has data

  if (aNotBefore > bNotBefore) {
    return 1;
  } else if (aNotBefore < bNotBefore) {
    return -1;
  } else {
    return 0;
  }
};

const authReducer = (state: IAuthState, action: AuthAction): IAuthState => {
  switch (action.type) {
    case AuthActionTypes.DEBUG: {
      return { ...state, debugToggle: !state.debugToggle };
    }
    case AuthActionTypes.SESSION_CREATED: {
      return { ...state, ...action.payload, isFetchingSession: false, sessionFetchFailed: false, sessionFetched: true };
    }
    case AuthActionTypes.SESSION_UPDATED: {
      return { ...state, ...action.payload, isFetchingSession: false, sessionFetchFailed: false, sessionFetched: true };
    }
    case AuthActionTypes.FETCH_SESSION_REQUEST: {
      return { ...state, isFetchingSession: true };
    }
    case AuthActionTypes.FETCH_SESSION_FAILURE: {
      return { ...state, isFetchingSession: false, sessionFetchFailed: true, sessionFetched: true };
    }
    case AuthActionTypes.SESSION_DELETED: {
      return { ...initialAuthState };
    }
    case AuthActionTypes.FETCH_PRODUCTS_FAILURE:
    case AuthActionTypes.SERVER_ERROR: {
      return { ...state, isFetchingProducts: false, productFetchFailed: true };
    }
    case AuthActionTypes.FETCH_PRODUCTS_REQUEST: {
      return { ...state, isFetchingProducts: true };
    }
    case AuthActionTypes.FETCH_PRODUCTS_SUCCESS:
    case AuthActionTypes.USER_PRODUCTS_UPDATED: {
      const products = {
        ...action.payload.userProducts,
        entryTickets: action.payload.userProducts.entryTickets
          ? [...action.payload.userProducts.entryTickets].sort(entryTicketDateAscendingSort)
          : [],
      };

      return {
        ...state,
        products,
        error: false,
        productsFetched: true,
        errorSource: null,
        productsFetchTime: action.payload.productsFetchTime,
        isFetchingProducts: false,
        productFetchFailed: false,
      };
    }
    case AuthActionTypes.CARD_REGISTERED: {
      const filled = {
        ...action.payload.registerCardResponse,
        willBeActivated: true,
      };
      if (!state.products) {
        return { ...state };
      }
      const itemIndex = state.products.seasonPasses.findIndex(
        (seasonPass) => seasonPass.orderRowId === filled.orderRowId,
      );
      const updatedSeasonPasses = [...state.products.seasonPasses];
      if (itemIndex > -1) {
        updatedSeasonPasses[itemIndex] = filled;
      } else {
        updatedSeasonPasses.push(filled);
      }

      return { ...state, products: { ...state.products, seasonPasses: updatedSeasonPasses } };
    }
    case AuthActionTypes.CARD_BOOKING_SUCCESSFUL: {
      if (!isNonEmptyArray(action.payload.bookings) || !state.products) {
        return { ...state };
      }

      const initialValue = state.products.seasonPasses;

      const updatedSeasonPasses = action.payload.bookings.reduce((seasonPasses, newBooking) => {
        const itemIndex = seasonPasses.findIndex((seasonPass) => seasonPass.barcode === newBooking.barcode);
        if (itemIndex === -1) {
          return seasonPasses;
        }

        //("CARD WITH BARCODE FOUND: ", newBooking.barcode);
        const modifiedSeasonPasses = [...seasonPasses];
        const seasonPass = modifiedSeasonPasses[itemIndex];

        seasonPass.bookings ??= {};

        const productId = action.payload.productId;

        if (!seasonPass.bookings[productId]) {
          //("Booking for card existing, but no booking for productId " + productId);
          seasonPass.bookings = { ...seasonPass.bookings, ...newBooking.bookings };
          return modifiedSeasonPasses;
        } else {
          //("Booking for card existing, merging new booking with current one (one booking for ID already exists");
          seasonPass.bookings[productId] = [...seasonPass.bookings[productId], ...newBooking.bookings[productId]];
          return modifiedSeasonPasses;
        }
      }, initialValue);

      return { ...state, products: { ...state.products, seasonPasses: updatedSeasonPasses } };
    }
    case AuthActionTypes.FETCH_GIFTS_REQUEST: {
      return { ...state, isFetchingGifts: true };
    }
    case AuthActionTypes.FETCH_GIFTS_SUCCESS: {
      const gifts = action.payload.giftsResponse.gifts;
      const giftsWithTrimmedDatesOnRow = gifts.map((gift) => ({
        ...gift,
        rows: gift.rows.map((row) => ({
          ...row,
          dateFrom: DateHelper.toStringYYYYMMDD(row.dateFrom),
          dateTo: DateHelper.toStringYYYYMMDD(row.dateTo),
        })),
      }));

      return {
        ...state,
        gifts: giftsWithTrimmedDatesOnRow,
        giftsFetched: true,
        isFetchingGifts: false,
        giftFetchFailed: false,
      };
    }
    case AuthActionTypes.FETCH_GIFTS_FAILURE: {
      return { ...state, giftsFetched: false, isFetchingGifts: false, giftFetchFailed: true };
    }
    case AuthActionTypes.FETCH_CONTACTLESS_SUMMARIES_REQUEST: {
      return { ...state, isFetchingContactlessOrders: true };
    }
    case AuthActionTypes.FETCH_CONTACTLESS_SUMMARIES_SUCCESS: {
      return {
        ...state,
        contactlessOrders: action.payload.response,
        isFetchingContactlessOrders: false,
        contactlessOrdersFetchFailed: false,
      };
    }
    case AuthActionTypes.FETCH_CONTACTLESS_SUMMARIES_FAILURE: {
      return { ...state, isFetchingContactlessOrders: false, contactlessOrdersFetchFailed: true };
    }
    case AuthActionTypes.FETCH_CONTACTLESS_DETAILS_REQUEST: {
      const existingOrder = state.contactlessOrderDetails[action.payload.orderId] ?? {};
      return {
        ...state,
        contactlessOrderDetails: {
          ...state.contactlessOrderDetails,
          [action.payload.orderId]: { ...existingOrder, isFetching: true, fetchFailed: false },
        },
      };
    }
    case AuthActionTypes.FETCH_CONTACTLESS_DETAILS_SUCCESS: {
      const existingOrder = state.contactlessOrderDetails[action.payload.orderId] ?? {};
      return {
        ...state,
        contactlessOrderDetails: {
          ...state.contactlessOrderDetails,
          [action.payload.orderId]: {
            ...existingOrder,
            isFetching: false,
            fetchFailed: false,
            order: action.payload.response,
          },
        },
      };
    }
    case AuthActionTypes.FETCH_CONTACTLESS_DETAILS_FAILURE: {
      const existingOrder = state.contactlessOrderDetails[action.payload.orderId] ?? {};
      return {
        ...state,
        contactlessOrderDetails: {
          ...state.contactlessOrderDetails,
          [action.payload.orderId]: { ...existingOrder, isFetching: false, fetchFailed: true },
        },
      };
    }
    case AuthActionTypes.CONTACTLESS_VISITORS_UPDATED: {
      const updatedVisitor = action.payload.visitor;
      const visitorToUpdate = state.products?.contactless.visitors.find(
        (visitor) => visitor.visitorId === updatedVisitor.visitorId,
      );
      if (!state.products || !visitorToUpdate) {
        return { ...state };
      }

      const updatedVisitors = state.products.contactless.visitors.map((visitor) =>
        visitor.visitorId === updatedVisitor.visitorId ? updatedVisitor : visitor,
      );
      return { ...state, products: { ...state.products, contactless: { visitors: updatedVisitors } } };
    }
    case AuthActionTypes.SET_CONTACTLESS_VISITORS: {
      const visitors = Object.values(action.payload);
      const smartWristbands = visitors.filter(isTruthy);

      const isDifference = smartWristbands.some((smartWristband) => {
        const correspondingVisitor = state.products?.contactless.visitors.find(
          (visitor) => visitor.visitorId === smartWristband.visitorId,
        );

        if (!correspondingVisitor) {
          // If a corresponding visitor is not found, this is a new wristband
          return true;
        }

        // If a corresponding visitor is found, compare it with the smartWristband
        return JSON.stringify(smartWristband) !== JSON.stringify(correspondingVisitor);
      });

      if (!isDifference) {
        return state;
      }

      return {
        ...state,
        products: state.products ? { ...state.products, contactless: { visitors: smartWristbands } } : undefined,
      };
    }
    case AuthActionTypes.SET_SAVED_PAYMENT_METHOD: {
      return { ...state, savedPaymentMethod: action.payload };
    }
    default:
      return exhaustiveCheck(action);
  }
};

export { authReducer, initialAuthState };
