// @ts-strict-ignore
import {
  AuthActionTypes,
  AuthAction,
  FetchProductsSuccessAction,
  SessionCreatedAction,
  SessionUpdatedAction,
} from "../types/auth-types";
import MyParksService from "../services/myparks-service";
import { extract } from "@/core/helpers/object-helper";
import DateHelper, { createDate } from "@/core/helpers/date-helper";
import Cookies from "js-cookie";

type ActionMiddleware = {
  (action: AuthAction): AuthAction;
};

const actionHasPayload = (action: AuthAction): action is AuthAction & { payload: object } => {
  return "payload" in action;
};

const addDebugTimeStamp = (action: AuthAction) => {
  if (actionHasPayload(action)) {
    action.payload = { ...action.payload, debugDate: createDate() };
    return action;
  }
  return action;
};

const saveAntiCsrfTokenToHelper = (action: SessionCreatedAction | SessionUpdatedAction) => {
  MyParksService.updateAuth(action.payload);
  return action;
};

const saveSessionAsCookie = (action: AuthAction) => {
  const cookieString = extract(action, "payload.cookieString", undefined);
  if (cookieString) {
    const date = createDate();
    const expire = createDate(date.setFullYear(date.getFullYear() + 10));

    Cookies.set("session", cookieString, { expires: expire, path: "/" });
  }

  return action;
};

const removeSessionCookie = (action: AuthAction) => {
  Cookies.remove("session", { path: "/" });

  return action;
};

const saveFetchTimeStamp = (action: FetchProductsSuccessAction) => {
  const now = createDate();
  return { ...action, payload: { ...action.payload, productsFetchTime: DateHelper.toStringTimeYYYYMMDDHHMM(now) } };
};

const middlewareMap = new Map<AuthActionTypes, Array<ActionMiddleware>>();
middlewareMap
  .set(AuthActionTypes.DEBUG, [addDebugTimeStamp])
  .set(AuthActionTypes.SESSION_CREATED, [saveAntiCsrfTokenToHelper, saveSessionAsCookie])
  .set(AuthActionTypes.SESSION_UPDATED, [saveAntiCsrfTokenToHelper, saveSessionAsCookie])
  .set(AuthActionTypes.SESSION_DELETED, [removeSessionCookie])
  .set(AuthActionTypes.USER_PRODUCTS_UPDATED, [saveFetchTimeStamp]);

const actionMiddleware = (action: AuthAction) => {
  const middlewaresForType = middlewareMap.get(action.type);
  if (middlewaresForType) {
    return middlewaresForType.reduce((prevAction, middleware) => middleware(prevAction), action);
  }

  return action;
};

export default actionMiddleware;
