// store.js
import * as React from "react";
import { authReducer, initialAuthState } from "./auth-reducer";
import { IAuthState, IAuthDispatch, AuthAction } from "../types/auth-types";
import actionMiddleware from "./auth-action-middleware";

const AuthContext = React.createContext<IAuthState>(initialAuthState);

const AuthDispatchContext = React.createContext<IAuthDispatch>(() => {
  return;
});

const AuthDispatchContextConsumer = AuthDispatchContext.Consumer;

const AuthContextConsumer = AuthContext.Consumer;

const reducerWithMiddleWare = (state: IAuthState, action: AuthAction) => {
  // enrich action payload middleware
  action = actionMiddleware(action);
  return authReducer(state, action);
};

type AuthContextProviderParams = { children: React.ReactNode };
const AuthContextProvider = ({ children }: AuthContextProviderParams) => {
  const [state, dispatch] = React.useReducer(reducerWithMiddleWare, initialAuthState);

  return (
    <AuthContext.Provider value={state}>
      <AuthDispatchContext.Provider value={dispatch}>{children}</AuthDispatchContext.Provider>
    </AuthContext.Provider>
  );
};

const useAuthState = (): IAuthState => {
  const context = React.useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuthState must be used within a AuthProvider");
  }
  return context;
};

const useAuthDispatch = (): IAuthDispatch => {
  const context = React.useContext(AuthDispatchContext);
  if (context === undefined) {
    throw new Error("useAuthDispatch must be used within a AuthProvider");
  }
  return context;
};

export {
  AuthContext,
  AuthContextProvider,
  AuthDispatchContextConsumer,
  AuthContextConsumer,
  useAuthState,
  useAuthDispatch,
};
